// The lock runs on a thread of its own, started while the write holds the guard and joined once
    // the operation has returned, so it can take effect only after the write it arrived during.
    private fun lockedMidWrite(): Outcome<String, VaultError> {
        var locking: Thread? = null
        file.onWrite = {
            locking = Thread { session.lock(LockReason.Manual) }.also { it.start() }
        }
        val outcome = runBlocking { session.generateHotpCode(HOTP_ID) }
        locking?.join()
        return outcome
    }

// The timeout the cases run the handshake under. What a wait on it ends is a peer's silence rather
// than a slow machine: a peer that never writes has nothing to send however long it is given.
private const val HANDSHAKE_MILLIS = 250

// The arrays are copies the password fields handed over and no holder owns them. A lock or a
    // closing window cancels this scope mid-derivation, so the zeroing sits in a finally.
    fun run(scope: CoroutineScope, vararg passwords: CharArray, work: suspend () -> Outcome<*, E>) {
        isBusy = true
        error = null
        scope.launch {
            try {
                error = (work() as? Outcome.Failure)?.error
            } finally {
                passwords.forEach { it.fill(Char.MIN_VALUE) }
                isBusy = false
            }
        }
    }

