// The vault takes the policy only once the file has, so a refused write leaves the stored policy
    // and the published one in agreement.
    suspend fun setPolicy(policy: SecurityPolicy): Outcome<Unit, VaultCommitError> =
        onOpenVault(VaultError.VaultClosed) { open ->
            commit(open, open.body.copy(policy = policy), Unit)
        }

// Null where the file is the owner's alone. A mount can take the mode passed to open(2) and discard
// it, and reading it back is what turns that into a refused write rather than a file left readable.
private fun restriction(files: ExportAccess, path: Path, isPosix: Boolean): FileWriteError? {
    if (isPosix) {
        return if ((files.permissionsOf(path) - OWNER_ONLY).isEmpty()) null else ExportError.NotRestricted
    }
    // Off POSIX no creation attribute carries a mode, so the empty file takes an owner-only entry
    // before it holds anything. A filesystem offering neither is one nothing is written to.
    val view = Files.getFileAttributeView(path, AclFileAttributeView::class.java) ?: return ExportError.NotRestricted
    view.acl = listOf(
        AclEntry.newBuilder()
            .setType(AclEntryType.ALLOW)
            .setPrincipal(view.owner)
            .setPermissions(AclEntryPermission.entries.toSet())
            .build(),
    )
    return null
}

// A row left in its stored place is carried off screen by an edge scroll, and a lazy list disposes
// the item it left behind, gesture and all. So the list is rearranged under the pointer as it goes.
@Stable
class RowDragState {
    var draggedId: String? by mutableStateOf(null)
        private set

    var startIndex by mutableStateOf(NO_ROW)
        private set

    var targetIndex by mutableStateOf(NO_ROW)
        private set

    private var traveled by mutableStateOf(0f)
    private var startTop = 0
    private var height = 0

    val isDragging: Boolean get() = draggedId != null

    val centerY: Float get() = startTop + traveled + height / 2f

    fun start(id: String, index: Int, rows: List<RowBounds>) {
        val row = rows.firstOrNull { it.index == index } ?: return
        draggedId = id
        startIndex = index
        targetIndex = index
        startTop = row.top
        height = row.height
        traveled = 0f
    }

    fun dragBy(amountY: Float, rows: List<RowBounds>) {
        if (!isDragging) return
        traveled += amountY
        retarget(rows)
    }

    fun retarget(rows: List<RowBounds>) {
        if (isDragging) targetIndex = dropIndex(centerY, rows, targetIndex)
    }

    fun translationFor(currentTop: Int): Float = if (isDragging) startTop + traveled - currentTop else 0f

    fun release(): RowMove? {
        val move = draggedId
            ?.takeIf { targetIndex != startIndex && targetIndex != NO_ROW }
            ?.let { RowMove(it, targetIndex) }
        draggedId = null
        traveled = 0f
        if (move == null) settle()
        return move
    }

    fun settle() {
        draggedId = null
        startIndex = NO_ROW
        targetIndex = NO_ROW
        traveled = 0f
    }
}

