// Case-insensitive because the list holds lowercase forms, and capitalising a common password
// leaves it as guessable as it was.
private fun matches(candidate: String, password: CharArray): Boolean {
    if (candidate.length != password.size) return false
    for (index in candidate.indices) {
        if (candidate[index] != password[index].lowercaseChar()) return false
    }
    return true
}

// Closing the channel releases every lock this JVM holds on the file, so the close happens
    // whether or not the release above it does. A second call finds both already done, which is fine.
    private fun release(lock: FileLock, channel: FileChannel) {
        try {
            if (lock.isValid) lock.release()
        } catch (e: IOException) {
            LOGGER.log(System.Logger.Level.DEBUG, "the instance lock did not release cleanly", e)
        } finally {
            closeChannel(channel)
        }
    }

// The clipboard belongs to the toolkit thread. A flavour it does not hold is an ordinary answer, and
// so is contents that changed between the offer and the read.
internal suspend fun clipboardImage(): BufferedImage? = withContext(Dispatchers.Swing) {
    try {
        Toolkit.getDefaultToolkit().systemClipboard.getContents(null)
            ?.takeIf { it.isDataFlavorSupported(DataFlavor.imageFlavor) }
            ?.getTransferData(DataFlavor.imageFlavor) as? BufferedImage
    } catch (e: IllegalStateException) {
        LOGGER.log(System.Logger.Level.WARNING, "the clipboard could not be read for an image", e)
        null
    } catch (_: HeadlessException) {
        null
    } catch (_: UnsupportedFlavorException) {
        null
    } catch (e: IOException) {
        LOGGER.log(System.Logger.Level.WARNING, "the clipboard could not be read for an image", e)
        null
    }
}

